scan_linter_check.script:
(function(engine) {
    if (!engine.rootNode || new global.EcsContext(engine.current).clientKind() !== 'client') {
        return;
    }
    var ast = new global.EcsAst(engine.rootNode);
    var hits = new global.EcsClientScript(ast, 'client').domManipulation();
    var report = new global.EcsReport(engine, {
        ruleId: 'SN-CLIENT-003',
        title: 'Direct DOM manipulation in a client script',
        recommendation: 'Use the g_form, g_user and GlideForm APIs (setValue, setDisplay, setVisible, addDecoration, showFieldMsg and so on) instead of reaching into the page. DOM access breaks when the UI changes and does not work in Service Portal or Workspace.'
    });
    for (var i = 0; i < hits.length; i++) {
        report.add(hits[i].node, hits[i].message);
    }
    report.flush();
})(engine);
